<template><div class="page"><div class="toolbar"><h2>用户管理</h2><div class="filters"><el-input v-model="keyword" clearable placeholder="用户名或姓名" @keyup.enter="search"/><el-button @click="search">查询</el-button></div></div><PageTable title="用户列表" :rows="rows" :columns="columns" :total="total" :page="page" :loading="loading" @page-change="changePage"><template #actions><el-button type="primary" @click="openCreate">新增用户</el-button></template><template #rowActions="{row}"><el-button size="small" type="primary" @click="openEdit(row)">编辑</el-button><el-button size="small" type="danger" :disabled="row.username==='admin'" @click="remove(row)">删除</el-button></template></PageTable>
<el-dialog v-model="dialog" :title="form.id?'编辑用户':'新增用户'" width="540px"><el-form label-width="90px"><el-form-item label="用户名" required><el-input v-model="form.username" :disabled="!!form.id"/></el-form-item><el-form-item :label="form.id?'重置密码':'密码'" :required="!form.id"><el-input v-model="form.password" type="password" show-password :placeholder="form.id?'留空表示不修改':'至少6位'"/></el-form-item><el-form-item label="姓名" required><el-input v-model="form.realName"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="所属电站"><el-input-number v-model="form.stationId" :min="1"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import PageTable from '@/components/common/PageTable.vue';import { deleteUser,listUsers,saveUser,updateUser } from '@/api/user'
const rows=ref<any[]>([]),total=ref(0),keyword=ref(''),page=ref(1),loading=ref(false),dialog=ref(false),saving=ref(false);const form=reactive<any>({});const columns=[{prop:'username',label:'用户名'},{prop:'realName',label:'姓名'},{prop:'email',label:'邮箱'},{prop:'status',label:'状态'},{prop:'stationId',label:'所属电站'}]
const reset=()=>Object.assign(form,{id:null,username:'',password:'',realName:'',email:'',stationId:null,status:'ENABLED'});const load=async()=>{loading.value=true;try{const r:any=await listUsers({page:page.value,size:10,keyword:keyword.value});rows.value=r.data.records;total.value=r.data.total}finally{loading.value=false}};const search=()=>{page.value=1;load()};const changePage=(v:number)=>{page.value=v;load()};const openCreate=()=>{reset();dialog.value=true};const openEdit=(r:any)=>{Object.assign(form,r,{password:''});dialog.value=true};const submit=async()=>{if(!form.username||!form.realName||(!form.id&&form.password.length<6))return ElMessage.warning('请完整填写用户名、姓名和至少6位密码');saving.value=true;try{form.id?await updateUser(form.id,form):await saveUser(form);dialog.value=false;ElMessage.success('保存成功');load()}finally{saving.value=false}};const remove=async(r:any)=>{await ElMessageBox.confirm(`确认删除用户“${r.username}”？`,'删除确认',{type:'warning'});await deleteUser(r.id);ElMessage.success('已删除');load()};onMounted(load)
</script><style scoped>.filters{display:flex;gap:10px;width:420px}.filters .el-input{flex:1}</style>
